package org.joda.time;

import java.io.*;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.convert.FromString;
import org.joda.convert.ToString;
import org.joda.time.base.BaseDateTime;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractReadableInstantFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MutableDateTime_addYears_TriageGen1Test {

    @Test
    public void testAddYears_Positive() {
        // Test adding positive years
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 12, 0, 0, 0);
        dt.addYears(5);
        assertEquals(2025, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddYears_Negative() {
        // Test adding negative years (subtracting)
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 12, 0, 0, 0);
        dt.addYears(-5);
        assertEquals(2015, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddYears_Zero() {
        // Test adding zero years
        MutableDateTime dt = new MutableDateTime(2020, 5, 20, 10, 30, 0, 0);
        dt.addYears(0);
        assertEquals(2020, dt.getYear());
        assertEquals(5, dt.getMonthOfYear());
        assertEquals(20, dt.getDayOfMonth());
    }

    @Test
    public void testAddYears_LeapYearToNonLeapYear() {
        // Test edge case: Feb 29th to a non-leap year (should adjust to Feb 28th)
        MutableDateTime dt = new MutableDateTime(2020, 2, 29, 12, 0, 0, 0);
        dt.addYears(1);
        assertEquals(2021, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(28, dt.getDayOfMonth());
    }

    @Test
    public void testAddYears_NonLeapYearToLeapYear() {
        // Test edge case: Feb 28th to a leap year
        MutableDateTime dt = new MutableDateTime(2021, 2, 28, 12, 0, 0, 0);
        dt.addYears(3); // 2024 is a leap year
        assertEquals(2024, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(28, dt.getDayOfMonth());
    }

    @Test
    public void testAddYears_EndOfMonth() {
        // Test adding years to the end of a month
        MutableDateTime dt = new MutableDateTime(2023, 1, 31, 12, 0, 0, 0);
        dt.addYears(1);
        assertEquals(2024, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(31, dt.getDayOfMonth());
    }

    @Test
    public void testAddYears_LargeValue() {
        // Test adding a very large number of years
        MutableDateTime dt = new MutableDateTime(1000, 1, 1, 0, 0, 0, 0);
        dt.addYears(8000);
        assertEquals(9000, dt.getYear());
    }
}
